pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping.
    let mut score = pr;
    score += 30.0 * pr_norm * pr_norm * (0.5 + progress);

    // Penalize very large post residual more aggressively as stream progresses.
    score += 40.0 * pr_norm.powi(3) * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual) relative to bin capacity.
    score -= 25.0 * (1.0 - pr_norm).powi(2);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // Coupling with mean residual: avoid bins far from the mean (creates fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + progress);

    // Lookahead: penalize if post residual cannot fit the next item but is close to it (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let waste = (nxt - pr) / cap;
            score += 20.0 * waste * (0.4 + 0.6 * progress);
        } else {
            // Reward bins that can also host the next item.
            score -= 10.0 * (1.0 - ((pr - nxt) / cap)).max(0.0);
        }
    }

    // Mild penalty for opening new bins late in the stream when many bins are open.
    score += (open_bins_count as f64).sqrt() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-classes of capacity
    let item_class = item_size * 4 / bin_capacity; // 0..3
    let post_class = post_residual * 4 / bin_capacity;

    // Reward tight fits: exact fill is perfect
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space by harmonic class of leftover
        match post_class {
            0 => score -= 8.0,  // tiny leftover, likely reusable by small items
            1 => score += 6.0,  // awkward leftover
            2 => score += 10.0, // half-empty: worst dead space
            _ => score += 2.0,  // large leftover still fairly usable
        }
    }

    // Lookahead coupling: does the leftover fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Reward chainability, scaled by how tight the chain is
        score -= 12.0 - gap * 0.15;
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize more if leftover is small
        score += post_class as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if the fit here is poor
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; make it unattractive for good fits
        score += 25.0;
        if item_class >= 2 {
            // Big items are fine in fresh bins
            score -= 18.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // reserving fresh bin for sequence of large items
        }
    }

    // Stream progression: early on, be conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (open_bins_count as f64).sqrt();

    // Slight preference for bins below mean residual (balance load)
    score += ((bin_residual as f64 - mean_residual) * 0.05).clamp(-4.0, 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that cannot fit even the smallest plausible item (<= 10)
    // is pure waste; a gap below ~25 is unlikely to fit future mid-size items.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 25 {
        score += 8.0 + (25.0 - post_residual as f64) * 0.5;
    }

    // Reward near-perfect fits proportionally to how much of the item is packed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Tight-fit bonus: post_residual very small relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 12.0 / (1.0 + tightness * 4.0);
    }

    // Open-bin pressure: prefer compacting into fewer bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it;
    // if next item barely misses, penalize leaving that tempting gap.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 4.0;
        }
    }

    // Slight preference for bins tighter than the current mean residual
    // (keeps large gaps free for large future items).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: make empty bins moderately unattractive unless
    // placement in existing bins is truly bad (dead-space penalties above
    // can still let the new bin win).
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    if next_item_size > 0 {
        // Aggressive 2-step lookahead: reward bins whose post_residual
        // closely matches the next item's size.
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - match_gap / (bin_capacity as f64)).max(-1.0);

        // Perfect chain: this item leaves exactly the space the next item needs.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Item can't even fit the next item: dead space risk if post_residual is tiny
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // tiny unusable sliver
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far below mean are already tight;
    // filling them is good (they become fully used).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Penalize opening a new bin unless the item is huge relative to what's open
        // or there are no fitting bins.
        let pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (item_size as f64 / bin_capacity as f64).powf(2.0)
        };
        score = bin_capacity as f64 - 10.0 * pressure - (post_residual as f64) * 0.5;
        // Late in the stream, avoid opening new bins even more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: very small post_residual is fine, but mid-range
    // leftovers (hard to fill later) get an extra quadratic penalty.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 1.5 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 6.0;
        } else if post_residual >= next_item_size {
            score -= 1.0 + 0.02 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.5 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0;
    } else {
        // When many bins fit, mild penalty to encourage spreading across bins.
        score += 0.15 * (fitting_bins_count as f64).min(8.0);
    }

    // New-bin candidate logic: opening a bin is only attractive when this bin
    // would otherwise be a poor fit or when global residuals are already tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_here = (bin_residual - item_size) as f64;
        // Penalize new bin; relax penalty late in the stream or when
        // mean residual across open bins is small (few good homes left).
        let mut new_bin_penalty = 5.0 + 0.03 * (item_size as f64);
        new_bin_penalty -= 2.0 * progress;
        new_bin_penalty -= (mean_residual / cap).min(1.0) * 2.0;
        // If item is large, a fresh bin gives a clean home.
        new_bin_penalty -= 0.02 * item_size as f64;
        score += new_bin_penalty.max(0.5) + waste_here * 0.01;
    }

    // Mild preference for fuller bins when many bins are open (bin consolidation).
    score += 0.02 * open_bins_count as f64 * (1.0 - (bin_residual as f64) / cap);

    // Time-horizon coupling: early in stream, be conservative (keep bins
    // flexible); late in stream, greedily fill whatever fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Smooth polynomial coupling: penalize residual more as stream progresses
    let coupling = norm_pr * (1.0 + progress * norm_pr * 10.0);
    score += 20.0 * coupling;
    // Reward tight fits with smooth quadratic term
    let tight = 1.0 - norm_pr;
    score -= 15.0 * tight * tight * (1.0 + progress);
    // Last-chance bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // Lookahead: reward bins that can also host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    }
    // Penalize deviation from mean residual (smooth)
    score += 0.5 * (pr - mean_residual).abs();
    // New-bin candidate: mild penalty so it loses to good fits
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot class" does the leftover fall into?
    // Dead space classes: residuals that can host only tiny items are penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward residuals in useful classes (can still host medium items).
    if post_residual >= quarter {
        score -= 12.0 * ((post_residual as f64) / (bin_capacity as f64));
    } else if post_residual >= eighth {
        score -= 4.0;
    } else if post_residual > 0 {
        // Very small dead space: penalize proportionally to how dead it is.
        score += (eighth - post_residual) as f64 * 0.8;
    }

    // Modulo coupling: post_residual mod 10 — "granularity" harmony with typical item sizes.
    let gran = post_residual % 10;
    if gran == 0 {
        score -= 6.0; // perfectly aligned leftover, likely reusable exactly
    } else if gran >= 5 {
        score -= 2.0 * (gran as f64 - 5.0) / 5.0;
    } else {
        score += (5 - gran) as f64 * 0.6;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // prefer leaving slack in harmonically nice amounts
            if slack % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 5.0 - 0.5 * (slack % 10) as f64;
            }
        } else {
            // next item won't fit here: penalize by how far off (dead-end risk)
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline so it's chosen only
    // when all open bins have bad scores; scale with stream progression.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // open new bin early when many items remain and current bins are fragmented
        if mean_residual < 20.0 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (>=1) can usefully fill later
    // are heavily penalized. A gap of 0 is perfect (exact fit).
    if post_residual > 0 {
        // Small gaps (< 10, below minimum item size) are pure dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 25 {
            // Moderately small gaps are risky: penalize proportionally.
            score += (25.0 - post_residual as f64) * 2.5;
        }
    } else {
        // Exact fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fills generally: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new bin is cheaper, so penalize placements
    // that leave large residuals when bin count is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(1.0);
    score += (mean_residual - post_residual as f64).abs() * 0.15 * bin_pressure;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use this residual: penalize leaving it.
            score += post_residual as f64 * 0.2;
        }
    }

    // New-bin candidate handling: an empty bin should only win when all fits
    // into open bins are poor. Give it a baseline cost that scales with
    // progress and number of open bins (opening gets more expensive later).
    if bin_residual == bin_capacity {
        score = 50.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // If the residual left after placing here would be dead space anyway,
        // opening fresh is more attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter bins among many options.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Global pressure: when many bins are open relative to stream length, discourage new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are underused.
        score += 30.0 + 20.0 * (mean_residual / bin_capacity as f64);
        score -= 10.0 * progress;
    } else {
        score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);
    }

    // Mild time-coupling: late in the stream, prefer consolidating into residual mass.
    score += 5.0 * progress * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: non-linear polynomial in normalized post residual.
    let base = 3.0 * rn.powf(1.4) + 2.0 * rn * rn;

    // Stream-progress coupling: later in stream, penalize residual more (tighten packing).
    let progress_coupling = progress * 2.5 * rn * (1.0 - rn);

    // Dead-space penalty: residual too small to fit typical future items (>=10).
    let dead = if r > 0.0 && r < 10.0 { (10.0 - r) * 1.5 } else { 0.0 };

    // Lookahead: reward if post residual can still hold next item, penalize exact-waste.
    let look = if next_item_size > 0 {
        if (r as u64) >= (next_item_size as u64) && (post_residual as u64) < (next_item_size as u64) {
            -1.0 // perfect chain fit
        } else if (post_residual as u64) >= (next_item_size as u64) {
            -0.5
        } else {
            0.5
        }
    } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 { -4.0 } else { 0.0 };

    // New-bin candidate: empty bin should only win when open bins are poor fits.
    let new_bin_penalty = if bin_residual == bin_capacity {
        6.0 + 3.0 * (1.0 - progress) + 0.5 * open_bins_count as f64
    } else {
        0.0
    };

    // Slight tie-break by mean residual divergence.
    let spread = (mean_residual - rn * cap).abs() * 0.01;

    base + progress_coupling + dead + look + last_chance + new_bin_penalty + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity divided into decile classes.
    // Residuals in low classes (0..=10) are near-dead space -> penalize mildly,
    // but perfect class 0 is a perfect fit -> reward strongly.
    let class = post_residual / (bin_capacity / 10).max(1);
    match class {
        0 => score -= 40.0,          // perfect / near-perfect fit
        1 => score -= 12.0,          // very tight, still useful
        2 | 3 => score += 3.0,       // mid-range, neutral-ish
        4 | 5 | 6 => score += 8.0,   // half-full bins kept flexible
        _ => score += 15.0,          // mostly empty: prefer other bins first
    }

    // Modulo arithmetic: residuals that are multiples of common small item
    // sizes (10, 20, 25) remain "packable" -> reward harmonic alignment.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (20.0 - slack as f64).max(0.0);
        // Perfect lookahead fit (post_residual == next_item_size)
        if slack == 0 { score -= 25.0; }
    } else if next_item_size > 0 {
        // Next item cannot fit here: this residual becomes dead weight.
        score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current bin would leave a very awkward residual. Give the empty bin a
    // baseline penalty that shrinks as the stream progresses (late stream ->
    // consolidation matters more, prefer filling open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 30.0 - 20.0 * progress;
        // If no open bin fits well (post_residual would be tiny or the item
        // barely fits), opening a new bin is attractive.
        if post_residual <= 5 && bin_residual >= bin_capacity {
            score -= 25.0;
        }
    }

    // Slight preference to spread load when many bins are open and mean
    // residual is high (balance pressure).
    score -= 0.02 * mean_residual / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the minimum item (1) are less bad,
    // but gaps below the typical item size that can't fit next_item_size are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fit: reward strongly
        score -= 1000.0;
    } else if post_residual < 10 {
        // tiny unusable gap -> nearly perfect, reward
        score -= 300.0 - (post_residual as f64) * 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap can't fit the lookahead item: dead space until later
        score += 40.0 + (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward filling a bin that is the only option (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let pressure = open_bins_count as f64 * 3.0;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize when decent fits exist or few bins open.
        score += 80.0 + pressure * 2.0
            + if fitting_bins_count > 0 { 200.0 } else { 0.0 };
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Late in the stream, tighten up: avoid leaving mid-size gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // perfect 2-step fit: place here
        } else if post_residual >= next_item_size {
            // next item still fits in this bin afterwards
            score -= 20.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item would NOT fit after this placement -> dead space penalty
            score += 15.0 + 0.5 * diff as f64;
        }
    }

    // Penalize small unusable post-residual (dead space below typical item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare residual against mean residual: prefer bins that are already tight
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many items remain
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can absorb the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 1) Tightness reward: strongly favor placements that leave little dead space,
    //    with a non-linear quadratic penalty on leftover space.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * bin_capacity as f64;

    // 2) Lookahead coupling: if the next item fits exactly into post_residual,
    //    reward heavily; if next item is wasted by a large post_residual, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr && nxt > 0.0 {
            let gap = pr - nxt;
            // perfect chain fit -> big reward
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else if pr > 0.0 && nxt > pr {
            // leaving a residual too small for the next item: dead-space risk
            score += 0.5 * pr * (nxt / bin_capacity as f64);
        }
    }

    // 3) Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new bin
    //    unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 4.0 * progress;
    }

    // 4) New-bin candidate handling: an empty bin gets a moderate baseline so it is
    //    chosen only when no open bin offers a decent fit, but early in the stream
    //    (when bin count is low) spreading is cheaper.
    if bin_residual == bin_capacity {
        let spread_urgency = (open_bins_count as f64).ln().max(0.0);
        score = bin_capacity as f64 * (0.85 - 0.25 * progress) + spread_urgency;
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 * 0.5 {
            score -= 3.0; // fresh bin can host a chain of mid-size items
        }
    }

    // 5) Global pressure: when mean residual across open bins is low (bins nearly full),
    //    prefer using existing space more aggressively.
    score -= 0.05 * mean_residual * (1.0 - progress);

    // 6) Waste guard: never place a small item into a huge residual late in the stream
    //    if it creates a tiny unusable sliver.
    if pr > 0 && pr < 10 {
        score += 15.0; // unusable sliver penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly
    let progress_coupling = norm_pr * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Reward tight fits (post_residual near zero) with smooth term
    score -= fit * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize post-residuals that are unusable: smooth measure of how far
    // post_residual is from the "useful" range relative to next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (norm_pr - nx).abs();
        score += gap * gap * (1.0 + progress);
        // Reward if next item fits exactly
        score -= 0.5 * (1.0 - gap.abs().min(1.0)) * (1.0 - (norm_pr - nx).abs().max(0.0));
    } else {
        // last item: strongly prefer minimal post residual
        score += norm_pr * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty when many bins are open and this bin's residual deviates
    // from the mean residual (encourage consolidation)
    let mean_norm = mean_residual / cap;
    score += 0.3 * (norm_pr - mean_norm) * (norm_pr - mean_norm) * (open_bins_count as f64).ln().max(1.0) / (open_bins_count as f64).max(1.0);

    // Smoothly discourage opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 0.8 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are rewarded (wasted space is minimized).
    let r = post_residual;
    let class = r / 10; // integer division thresholds: 0..10 harmonic band
    match class {
        0 => score -= 25.0,           // near-perfect fit (r < 10)
        1 => score -= 18.0,           // excellent
        2 => score -= 12.0,
        3 => score -= 7.0,
        4 => score -= 3.0,
        _ => {}                        // large leftover: no bonus
    }

    // Modulo-arithmetic bonus: residues divisible by common item sizes
    // (10, 20, 25, 50) are reusable by typical future items.
    if r % 10 == 0 && r > 0 { score -= 6.0; }
    if r % 20 == 0 && r > 0 { score -= 4.0; }
    if r % 25 == 0 && r > 0 { score -= 4.0; }
    if r % 50 == 0 && r > 0 { score -= 3.0; }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            // next item fits: leftover after the chain is what matters
            let chain_left = r - next_item_size;
            score -= 10.0 - (chain_left as f64) * 0.15;
        } else {
            // next item cannot use this residue: mild penalty, worse if
            // the overshoot is small (teasing near-miss)
            let overshoot = next_item_size - r;
            if overshoot <= 10 { score += 4.0; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize so it is chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Tightness term: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Contextual pressure: many open bins with high mean residual means
    // fragmentation; prefer bins below the mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Cap the dead-space penalty so extreme residues don't dominate
    // everything: large leftovers are discouraged smoothly.
    if r > 60 {
        score += (r - 60) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the next item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use this residual: dead space confirmed.
        score += 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Compare against mean residual: bins far below mean residual are more reusable.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // New-bin candidate: prefer it only if all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; dead-space penalties above make poor open bins worse.
        score += 2.0;
        if fitting_bins_count > 0 {
            // Slight bias to reuse existing bins when they fit reasonably.
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Post-residual leaves room for the next item (partial lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * next_item_size as f64;
        // Reward tighter fits: small slack beyond next item is good.
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else {
        // Dead space: post_residual can't hold next item; penalize proportionally.
        score += 1.5 * post_residual as f64;
        // Extra penalty if next item is large (wasted space more costly).
        score += 0.25 * next_item_size as f64;
    }

    // Compare against mean residual: bins with residual well above mean are
    // better candidates to absorb the item (keep tight bins for later).
    if (bin_residual as f64) > mean_residual {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; the perfect-match reward can still
        // override this if lookahead suggests a fresh bin is ideal.
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Opening fresh bin allows pairing current + next item.
            score -= 25.0;
        }
    }

    // Early in the stream, allow slightly more liberal bin opening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow here; slight penalty scaled by wasted potential.
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate: prefer opening a new bin when item is large and current
    // open-bin fits are poor, but discourage needless bin proliferation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let spread = (mean_residual - post_residual as f64).abs();
        // New bins are attractive early (room to consolidate) and for large items.
        let new_bin_bias = 25.0 + 45.0 * (1.0 - progress) - 20.0 * (open_bins_count as f64 / 10.0).min(3.0);
        score += new_bin_bias - 10.0 * (item_size as f64 / bin_capacity as f64) + 0.05 * spread;
        // Never open a new bin if this is a last-chance situation elsewhere.
        if fitting_bins_count <= 2 {
            score += 50.0;
        }
    }

    // Global pressure: many open bins -> prefer filling existing ones tightly.
    let pressure = (open_bins_count as f64 / 20.0).min(2.0);
    score -= pressure * fit_ratio * 10.0;

    // Mean-residual coupling: when mean residual is high, avoid leaving mid-size gaps.
    if post_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling: residual waste is penalized more strongly as the stream progresses
    let poly = 1.0 + 0.8 * progress * progress + 0.4 * progress;
    score *= poly;

    // Reward tight fits (small post_residual relative to capacity) with smooth saturation
    let tight = (1.0 - pr / cap).powi(3);
    score -= 10.0 * tight * (1.0 + 0.5 * progress);

    // Reward if the lookahead item fits exactly in the post-residual (perfect chaining)
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let chain = 1.0 - ((post_residual - next_item_size as u32) as f64) / cap;
        score -= 8.0 * chain * chain;
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use
        score += 4.0 * (1.0 - (next_item_size as f64 / cap)).powi(2);
