    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit bonus (zero dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small to ever fit the minimum item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    } else if post_residual < 20 {
        score += 60.0;
    }

    // Harmonic class reward: post_residual that is a clean fraction of capacity
    // (multiples of 25 or 10) tends to combine well with future items.
    let class_bonus = match post_residual % 25 {
        0 => 40.0,
        _ => match post_residual % 10 {
            0 => 20.0,
            _ => 0.0,
        },
    };
    score -= class_bonus;

    // Integer-division threshold: classify post_residual into coarse buckets.
    let bucket = post_residual / 10; // 0..=10
    score -= (bucket as f64) * 3.0; // prefer larger leftover space generally

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // reward tight-but-feasible next fit
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            // harmonic chain: next item leaves a clean residual too
            if (post_residual - next_item_size) % 25 == 0 {
                score -= 25.0;
            }
            let _ = nxt;
        } else {
            // next item cannot use this residual: penalize large trapped space
            score += 15.0 + 0.2 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to
    // bin_residual of all other open bins. Penalize new bins unless current
    // bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // mild base penalty so good existing fits win
        score += 30.0;
        // but if open bins are crowded (low mean residual), a fresh bin is fine
        score -= 0.3 * mean_residual;
        // early stream: allow more bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 50.0 * (1.0 - progress);
    }

    // Mild pressure against bin proliferation.
    score += 0.5 * open_bins_count as f64;

    // Small tie-break: prefer bins whose residual is close to item+next (tightness).
    score += 0.05 * ((bin_residual as f64) - (item_size as f64) - (next_item_size as f64)).abs();

    score
}

